class TestK8sProviderError:
    """Tests for the custom exception class."""

    def test_error_message_format(self):
        """Verifies the error message format."""
        err = K8sProviderError('deployment', 'create', 'disk full', 507)
        assert str(err) == "[K8sProvider] create failed for deployment: disk full"
        assert err.name == 'K8sProviderError'
        assert err.resource == 'deployment'
        assert err.operation == 'create'
        assert err.code == 507

    def test_error_without_code(self):
        """Tests the error when no HTTP code is provided."""
        err = K8sProviderError('service', 'delete', 'not found')
        assert err.code is None
        assert str(err) == "[K8sProvider] delete failed for service: not found"


