class TestApplyIntegration:
    """Integration-style tests for the full reconciliation loop."""

    @pytest.mark.asyncio
    async def test_apply_with_mixed_success_and_failure(self, provider, mock_k8s_module, sample_infra_spec):
        """
        Tests a scenario where the first resource fails but the second succeeds.
        Verifies that the loop continues and reports partial_failure.
        """
        provider.ensureNamespace = AsyncMock()

        # Simulate: deployment fails, service succeeds
        async def mock_reconcile(resource, namespace):
            if resource['type'] == 'deployment':
                raise K8sProviderError('deployment', 'create', 'quota exceeded', 403)
            return resource['name']

        provider.reconcileResource = AsyncMock(side_effect=mock_reconcile)

        result = await provider.apply(sample_infra_spec)

        assert result['status'] == 'partial_failure'
        assert result['appliedResources'] == ['web-service']

    @pytest.mark.asyncio
    async def test_apply_continues_after_error(self, provider, mock_k8s_module, sample_infra_spec):
        """
        Verifies that the apply loop does not stop on the first error.
        This is critical for the reconciliation loop semantics.
        """
        provider.ensureNamespace = AsyncMock()
        provider.reconcileResource = AsyncMock(side_effect=[
            K8sProviderError('deployment', 'create', 'fail 1', 500),
            'web-service',
            K8sProviderError('ingress', 'create', 'fail 2', 500),
            'config-map-1'
        ])

        # Add more resources to the spec to test multiple failures
        spec = {
            "version": "1.0",
            "metadata": {"namespace": "test-ns", "name": "test"},
            "resources": [
                {"type": "deployment", "name": "dep-1", "spec": {}},
                {"type": "service", "name": "svc-1", "spec": {}},
                {"type": "ingress", "name": "ing-1", "spec": {}},
                {"type": "configmap", "name": "cfg-1", "spec": {}},
            ]
        }

        result = await provider.apply(spec)

        assert result['status'] == 'partial_failure'
        assert 'svc-1' in result['appliedResources']
        assert 'cfg-1' in result['appliedResources']
        assert 'dep-1' not in result['appliedResources']
        assert 'ing-1' not in result['appliedResources']
        # Verify that reconcileResource was called 4 times (didn't stop early)
        assert provider.reconcileResource.await_count == 4

    @pytest.mark.asyncio
    async def test_apply_with_no_namespace_in_metadata(self, provider, mock_k8s_module):
        """Tests behavior when namespace is missing from metadata."""
        spec = {
            "version": "1.0",
            "metadata": {"name": "test"},
            "resources": []
        }

        # This should raise a KeyError or similar since namespace is accessed
        with pytest.raises(KeyError):
            await provider.apply(spec)


